CREATE TABLE admin_capabilities(actor_id INTEGER NOT NULL REFERENCES users(id), capability TEXT NOT NULL CHECK(capability='mapping_setup'), granted_by INTEGER NOT NULL REFERENCES users(id), reason TEXT NOT NULL, created TEXT NOT NULL, PRIMARY KEY(actor_id,capability));
CREATE TABLE mapping_configuration_drafts(id INTEGER PRIMARY KEY, source_json TEXT NOT NULL, source_sha256 TEXT NOT NULL, base_version INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('draft','validated','approved','active')), actor_id INTEGER NOT NULL REFERENCES users(id), approved_by INTEGER REFERENCES users(id), reason TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE professional_entries(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES users(id), actor_id INTEGER NOT NULL REFERENCES users(id), draft TEXT NOT NULL DEFAULT '{}', submitted TEXT, version INTEGER NOT NULL DEFAULT 0, updated TEXT NOT NULL, UNIQUE(student_id,actor_id));
CREATE TABLE professional_versions(entry_id INTEGER NOT NULL REFERENCES professional_entries(id), version INTEGER NOT NULL, body TEXT NOT NULL, created TEXT NOT NULL, PRIMARY KEY(entry_id,version));
